#include <WiFi.h>
#include <WebServer.h>
#include <Adafruit_NeoPixel.h>

#define LED_PIN 18
#define LED_COUNT 8

const char* WIFI_NAME = "ESP32-RGB";
const char* WIFI_PASS = "rgbcontrol8";

WebServer server(80);
Adafruit_NeoPixel strip(
    LED_COUNT, LED_PIN, NEO_GRB + NEO_KHZ800
);

struct Pixel {
    uint8_t r = 0;
      uint8_t g = 0;
        uint8_t b = 0;
          bool on = false;
};

Pixel px[LED_COUNT];
int brightness = 75;

void renderLeds() {
    strip.setBrightness(brightness * 255 / 100);

      for (int i = 0; i < LED_COUNT; i++) {
            if (px[i].on) {
                    strip.setPixelColor(i,
                            strip.Color(px[i].r, px[i].g, px[i].b));
            } else {
                    strip.setPixelColor(i, 0);
            }
      }

        strip.show();
}

String stateJson() {
    String s = "{\"brightness\":";
      s += brightness;
        s += ",\"pixels\":[";

          for (int i = 0; i < LED_COUNT; i++) {
                if (i) s += ",";
                    s += "{\"on\":";
                        s += px[i].on ? "true" : "false";
                            s += ",\"r\":";
                                s += px[i].r;
                                    s += ",\"g\":";
                                        s += px[i].g;
                                            s += ",\"b\":";
                                                s += px[i].b;
                                                    s += "}";
          }

            s += "]}";
              return s;
}

