                                          </label>
                                            <div class="row">
                                                <label>R <input id="r" type="number" min="0" max="255" value="255"></label>
                                                    <label>G <input id="g" type="number" min="0" max="255" value="30"></label>
                                                        <label>B <input id="b" type="number" min="0" max="255" value="0"></label>
                                                          </div>
                                                            <button class="action" onclick="applyColor()">Применить цвет</button>
