                                                                        светодиода хранится отдельно, даже если он выключен.</p>
                                                                        </div>

                                                                        <script>
                                                                        let pixels = Array.from({length:8},()=>({
                                                                            on:false,r:0,g:0,b:0
                                                                        }));
                                                                        let selected = new Set([0]);
                                                                        let active = 0;
                                                                        let brightness = 75;
                                                                        let busy = false;

                                                                        const $ = id => document.getElementById(id);
                                                                        const clamp = n => Math.max(0,Math.min(255,Number(n)||0));

                                                                        function mode(){
                                                                            return document.querySelector('input[name="mode"]:checked').value;
                                                                        }

                                                                        function draw(){
                                                                            $('grid').innerHTML = '';
                                                                              pixels.forEach((p,i)=>{
                                                                                    let d=document.createElement('div');
                                                                                        d.className='tile'+(selected.has(i)?' active':'')+
                                                                                              (p.on?' on':'');
                                                                                                  d.innerHTML =
                                                                                                        '<button onclick="choose('+i+')">'+
                                                                                                              '<div style="height:25px;border-radius:6px;background:'+
                                                                                                                    (p.on?'rgb('+p.r+','+p.g+','+p.b+')':'#171b24')+
                                                                                                                          '"></div><b>№'+(i+1)+'</b></button>'+
                                                                                                                                '<label class="small"><input type="checkbox" '+
                                                                                                                                      (selected.has(i)?'checked':'')+
                                                                                                                                            ' onchange="checkPixel('+i+',this.checked)"> Группа</label>'+
                                                                                                                                                  '<label class="small"><input type="checkbox" '+
                                                                                                                                                        (p.on?'checked':'')+
                                                                                                                                                              ' onchange="togglePixel('+i+',this.checked)"> Вкл.</label>';
                                                                                                                                                                  $('grid').appendChild(d);
                                                                              });
                                                                                $('which').textContent='Выбран светодиод №'+(active+1)+
                                                                                    '. В группе: '+selected.size;
                                                                        }

                                                                        function choose(i){
                                                                            active=i;
                                                                              if(mode()==='single') selected=new Set([i]);
                                                                                loadEditor();
                                                                                  draw();
