                                                                        async function request(url){
                                                                            try{
                                                                                  let res=await fetch(url);
                                                                                      if(!res.ok) throw new Error('HTTP '+res.status);
                                                                                          return await res.json();
                                                                            }catch(e){
                                                                                  alert('Нет связи с ESP32. Проверь Wi-Fi.');
                                                                                      throw e;
                                                                            }
                                                                        }
                                                                        async function togglePixel(i,on){
                                                                            pixels[i].on=on;
                                                                              draw();
                                                                                try{
                                                                                      await request('/set?i='+i+'&on='+(on?1:0));
                                                                                }catch(e){}
                                                                        }
                                                                        async function allOn(on){
                                                                            pixels.forEach(p=>p.on=on);
                                                                              draw();
                                                                                try{await request('/all?on='+(on?1:0));}catch(e){}
                                                                        }
                                                                        function loadEditor(){
                                                                            let p=pixels[active];
                                                                              $('r').value=p.r; $('g').value=p.g; $('b').value=p.b;
                                                                                updateColor();
                                                                        }
                                                                        function updateColor(){
                                                                            let r=clamp($('r').value),g=clamp($('g').value),
                                                                                  b=clamp($('b').value);
                                                                                    $('color').value='#'+[r,g,b].map(v=>
                                                                                        v.toString(16).padStart(2,'0')).join('');
                                                                        }
                                                                        ['r','g','b'].forEach(id=>$(id).addEventListener('input',updateColor));
                                                                        $('color').addEventListener('input',()=>{
                                                                            let h=$('color').value;
                                                                              $('r').value=parseInt(h.slice(1,3),16);
                                                                                $('g').value=parseInt(h.slice(3,5),16);
                                                                                  $('b').value=parseInt(h.slice(5,7),16);
                                                                        });
                                                                        async function applyColor(){
                                                                            let ids=mode()==='single'?[active]:Array.from(selected);
                                                                              if(ids.length===0){alert('Сначала выбери светодиоды группы');return;}
                                                                                let r=clamp($('r').value),g=clamp($('g').value),
                                                                                      b=clamp($('b').value);
                                                                                        for(let i of ids){
                                                                                              pixels[i].r=r;pixels[i].g=g;pixels[i].b=b;
                                                                                                  pixels[i].on=true;
                                                                                                      try{
                                                                                                              await request('/set?i='+i+'&on=1&r='+r+'&g='+g+'&b='+b);
                                                                                                      }catch(e){return;}
                                                                                        }
                                                                                          draw();
                                                                        }
