                                                                            brightness=Number($('bright').value);
                                                                              $('bv').textContent=brightness+'%';
                                                                        });
                                                                        $('bright').addEventListener('change',async()=>{
                                                                            try{await request('/brightness?v='+brightness);}catch(e){}
                                                                        });
                                                                        document.querySelectorAll('input[name="mode"]').forEach(el=>{
